  display: flex;
  visibility: hidden;
}
.modal .modal-content {
  max-width: 95%;
}
.modal .modal-background {
  transition: all 0.3s;
  opacity: 0;
}
.modal.is-active {
  visibility: visible;
}
.modal.is-active .modal-background {
  opacity: 1;
}
.modal.modal-fx-fadeInScale .modal-content {
  transform: scale(0.7);
  opacity: 0;
  transition: all 0.3s;
}
.modal.modal-fx-fadeInScale.is-active .modal-content {
  transform: scale(1);
  opacity: 1;
}
